// DS18B20 1-Wire digital thermometer on ESP32 DevKit (ESP32-WROOM-32)
// Bit-banged 1-Wire master implemented directly from the datasheet, no external libraries.
// Wiring: VDD -> 3V3, GND -> GND, DQ -> GPIO16 with a 4.7k pull-up to 3V3 (datasheet p.4 Fig.3, p.10).

#include <Arduino.h>

// ---- Pin assignment (matches the pins table) ----
const int DS18B20_DQ = 16;   // 1-Wire data line, open drain, external 4.7k pull-up to 3V3

// ---- ROM function commands (datasheet p.11) ----
const uint8_t CMD_READ_ROM = 0x33;
const uint8_t CMD_SKIP_ROM = 0xCC;

// ---- Memory / control function commands (datasheet p.14, Table 4 p.18) ----
const uint8_t CMD_CONVERT_T        = 0x44;
const uint8_t CMD_WRITE_SCRATCHPAD = 0x4E;
const uint8_t CMD_READ_SCRATCHPAD  = 0xBE;
const uint8_t CMD_READ_POWER       = 0xB4;

// ---- Scratchpad bytes 2..4 written with Write Scratchpad (p.8 Fig.7, p.9 Table 3) ----
// Configuration register layout: 0 R1 R0 1 1 1 1 1 ; R1=R0=1 -> 12-bit resolution -> 0x7F
const uint8_t TH_DEFAULT   = 0x7D;   // +125 C alarm high (alarms not used here)
const uint8_t TL_DEFAULT   = 0xC9;   // -55 C alarm low (two's complement)
const uint8_t CONFIG_12BIT = 0x7F;
const uint32_t TCONV_12BIT_MS = 750; // max 12-bit conversion time (p.9 Table 3, p.25)

const uint8_t DS18B20_FAMILY_CODE = 0x28; // p.6

static bool parasitePowered = false;

// ---------- Low-level line control (open-drain emulation) ----------
static inline void owDriveLow() {
  pinMode(DS18B20_DQ, OUTPUT);
  digitalWrite(DS18B20_DQ, LOW);
}
static inline void owRelease() {
  pinMode(DS18B20_DQ, INPUT);      // external 4.7k pull-up raises the line
}
static inline int owSample() {
  return digitalRead(DS18B20_DQ);
}

// Reset pulse + presence detect (p.14, Fig.11 p.18, AC table p.25):
// master holds low >= 480 us (tRSTL), releases; slave waits 15-60 us then pulls low 60-240 us.
bool owReset() {
  owDriveLow();
  delayMicroseconds(500);          // tRSTL >= 480 us
  noInterrupts();
  owRelease();
  delayMicroseconds(70);           // land inside the presence pulse window
  bool presence = (owSample() == LOW);
  interrupts();
  delayMicroseconds(430);          // complete tRSTH >= 480 us
  return presence;
}

// Write time slot (p.19, p.25): slot 60-120 us, recovery >= 1 us.
// Write 1: low for 1-15 us then release. Write 0: low for 60-120 us.
void owWriteBit(uint8_t bit) {
  noInterrupts();
  owDriveLow();
  if (bit) {
    delayMicroseconds(6);          // tLOW1 = 1..15 us
    owRelease();
    delayMicroseconds(64);         // finish 60 us slot + recovery
  } else {
    delayMicroseconds(60);         // tLOW0 = 60..120 us
    owRelease();
    delayMicroseconds(10);         // recovery
  }
  interrupts();
}

// Read time slot (p.19, Fig.13/14 p.21): master low >= 1 us, release,
// sample before 15 us after the falling edge (tRDV = 15 us max).
uint8_t owReadBit() {
  uint8_t bit;
  noInterrupts();
  owDriveLow();
  delayMicroseconds(3);            // tINIT > 1 us
  owRelease();
  delayMicroseconds(10);           // sample towards the end of the 15 us window
  bit = owSample() ? 1 : 0;
  interrupts();
  delayMicroseconds(53);           // complete 60 us slot + recovery
  return bit;
}

// All data is transferred LSB first (p.2, p.5)
void owWriteByte(uint8_t b) {
  for (int i = 0; i < 8; i++) {
    owWriteBit(b & 0x01);
    b >>= 1;
  }
}

uint8_t owReadByte() {
  uint8_t b = 0;
  for (int i = 0; i < 8; i++) {
    b >>= 1;
    if (owReadBit()) b |= 0x80;
  }
  return b;
}

// 1-Wire CRC-8, polynomial X^8 + X^5 + X^4 + 1 (p.6, Fig.6 p.8), LSB-first shift register.
// 0x8C is the bit-reflected form of the polynomial.
uint8_t owCrc8(const uint8_t *data, uint8_t len) {
  uint8_t crc = 0;
  while (len--) {
    uint8_t inbyte = *data++;
    for (int i = 0; i < 8; i++) {
      uint8_t mix = (crc ^ inbyte) & 0x01;
      crc >>= 1;
      if (mix) crc ^= 0x8C;
      inbyte >>= 1;
    }
  }
  return crc;
}

// Read Power Supply [B4h] (p.4, p.14): read slot returns 0 = parasite, 1 = external VDD
bool owReadPowerSupply() {
  if (!owReset()) return false;
  owWriteByte(CMD_SKIP_ROM);
  owWriteByte(CMD_READ_POWER);
  return owReadBit() == 0;   // true when parasite powered
}

// Write TH, TL and CONFIG to scratchpad bytes 2..4 (p.14). All three must be sent before a reset.
bool ds18b20WriteConfig(uint8_t th, uint8_t tl, uint8_t cfg) {
  if (!owReset()) return false;
  owWriteByte(CMD_SKIP_ROM);
  owWriteByte(CMD_WRITE_SCRATCHPAD);
  owWriteByte(th);
  owWriteByte(tl);
  owWriteByte(cfg);
  return true;
}

// Start a conversion and wait for it to finish (p.14 Convert T, p.19 note 1)
bool ds18b20Convert() {
  if (!owReset()) return false;
  owWriteByte(CMD_SKIP_ROM);
  owWriteByte(CMD_CONVERT_T);
  if (parasitePowered) {
    // Strong pull-up: drive DQ high for > tconv (p.3, p.19 note 1). ESP32 GPIO can supply the 1.5 mA needed.
    pinMode(DS18B20_DQ, OUTPUT);
    digitalWrite(DS18B20_DQ, HIGH);
    delay(TCONV_12BIT_MS);
    owRelease();
  } else {
    // Externally powered: device answers 0 on read slots while busy, 1 when done (p.14)
    uint32_t start = millis();
    while (owReadBit() == 0) {
      if (millis() - start > TCONV_12BIT_MS + 50) return false;
      delay(5);
    }
  }
  return true;
}

// Read the 9-byte scratchpad and verify its CRC (p.8, p.14, Table 5 p.22)
bool ds18b20ReadScratchpad(uint8_t sp[9]) {
  if (!owReset()) return false;
  owWriteByte(CMD_SKIP_ROM);
  owWriteByte(CMD_READ_SCRATCHPAD);
  for (int i = 0; i < 9; i++) sp[i] = owReadByte();
  return owCrc8(sp, 8) == sp[8];
}

// Convert scratchpad bytes 0 (LSB) and 1 (MSB) to degrees C.
// 16-bit sign-extended two's complement, LSB = 2^-4 = 0.0625 C at 12-bit (p.5 Table 2).
float ds18b20RawToCelsius(uint8_t lsb, uint8_t msb) {
  int16_t raw = (int16_t)(((uint16_t)msb << 8) | lsb);
  return raw / 16.0f;
}

void setup() {
  Serial.begin(115200);
  delay(200);
  owRelease();                     // bus idles high via the pull-up (p.10)
  Serial.println("DS18B20 on ESP32 (GPIO16)");

  if (!owReset()) {
    Serial.println("ERROR: no presence pulse. Check wiring and 4.7k pull-up on DQ.");
  }

  // Read ROM [33h]: family code, 48-bit serial, CRC (single device only, p.11)
  uint8_t rom[8];
  if (owReset()) {
    owWriteByte(CMD_READ_ROM);
    for (int i = 0; i < 8; i++) rom[i] = owReadByte();
    Serial.print("ROM: ");
    for (int i = 0; i < 8; i++) {
      if (rom[i] < 0x10) Serial.print('0');
      Serial.print(rom[i], HEX);
      Serial.print(' ');
    }
    Serial.println();
    if (rom[0] != DS18B20_FAMILY_CODE) Serial.println("WARNING: family code is not 0x28");
    if (owCrc8(rom, 7) != rom[7]) Serial.println("WARNING: ROM CRC mismatch");
  }

  // Detect power mode so we know whether a strong pull-up is required (p.4)
  parasitePowered = owReadPowerSupply();
  Serial.print("Power mode: ");
  Serial.println(parasitePowered ? "parasite (DQ strong pull-up used)" : "external VDD");

  // Set 12-bit resolution in the volatile scratchpad config (factory default is already 12-bit, p.9)
  if (ds18b20WriteConfig(TH_DEFAULT, TL_DEFAULT, CONFIG_12BIT)) {
    Serial.println("Configured 12-bit resolution (CONFIG = 0x7F)");
  }
}

void loop() {
  uint8_t sp[9];
  if (!ds18b20Convert()) {
    Serial.println("Conversion failed / timeout");
  } else if (!ds18b20ReadScratchpad(sp)) {
    Serial.println("Scratchpad CRC error, retrying");
  } else {
    float tc = ds18b20RawToCelsius(sp[0], sp[1]);
    float tf = tc * 9.0f / 5.0f + 32.0f;   // datasheet says host must convert to Fahrenheit (p.5)
    Serial.print("Temperature: ");
    Serial.print(tc, 4);
    Serial.print(" C  (");
    Serial.print(tf, 3);
    Serial.print(" F)  raw=0x");
    uint16_t raw = ((uint16_t)sp[1] << 8) | sp[0];
    if (raw < 0x1000) Serial.print('0');
    if (raw < 0x100) Serial.print('0');
    if (raw < 0x10) Serial.print('0');
    Serial.print(raw, HEX);
    Serial.print("  config=0x");
    Serial.println(sp[4], HEX);
    if (raw == 0x0550) Serial.println("Note: 0x0550 (+85 C) is the power-on reset value; conversion may not have run (p.5)");
  }
  delay(1000);
}
